/** Background style. Glass ships; Paper is the optional alternative from the design. */
export const BG_STYLE: "glass" | "paper" = "glass";

export const MODE_KEY = "rk-mode";
export const INTRO_KEY = "rk-intro-played";

/** Intro textures, per mode. Generated by `npm run intro:raster`. */
export const INTRO_ASSETS = {
  light: ["/intro/sun.webp", "/intro/trail-sun-a.webp", "/intro/trail-sun-b.webp"],
  dark: ["/intro/moon.webp", "/intro/trail-moon-a.webp", "/intro/trail-moon-b.webp"],
} as const;

/**
 * Runs in <head> before first paint:
 * - applies the saved mode (default light) so there is no flash;
 * - decides whether the intro plays: only when landing on `/`, once per
 *   session, and never under prefers-reduced-motion. Landing on another
 *   route also counts as "played", so a later visit to Home skips it;
 * - preloads the intro textures for the active mode when it will play.
 */
export const BOOT_SCRIPT = `(function(){
var d=document.documentElement,m='light';
try{m=localStorage.getItem('${MODE_KEY}')==='dark'?'dark':'light';}catch(e){}
d.setAttribute('data-mode',m);
try{
  var p=location.pathname,home=p==='/'||p==='/index'||p==='/index.html';
  var played=sessionStorage.getItem('${INTRO_KEY}');
  var still=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(home&&!played&&!still){
    d.setAttribute('data-intro','play');
    var assets=${JSON.stringify(INTRO_ASSETS)};
    assets[m].forEach(function(h){var l=document.createElement('link');l.rel='preload';l.as='image';l.href=h;document.head.appendChild(l);});
  }
  sessionStorage.setItem('${INTRO_KEY}','1');
}catch(e){}
})();`;
